{
  "iteration": 10,
  "pcvs": [
    {
      "name": "prefill_tokens",
      "expression": "0 if attn_metadata is None or attn_metadata.max_query_len <= 1 else attn_metadata.num_actual_tokens",
      "rationale": "Captures baseline prefill processing."
    },
    {
      "name": "prefill_second_block_rows",
      "expression": "0 if attn_metadata is None or attn_metadata.max_query_len <= 1 else max(0, attn_metadata.num_actual_tokens - 32 * attn_metadata.seq_lens.numel())",
      "rationale": "For the observed full causal prefills, counts query rows extending beyond the first 32-token context block instead of charging every row for the maximum context."
    },
    {
      "name": "decode_requests",
      "expression": "0 if attn_metadata is None or attn_metadata.max_query_len > 1 else attn_metadata.seq_lens.numel()",
      "rationale": "Captures baseline decode work independently of prefill."
    },
    {
      "name": "decode_extra_blocks",
      "expression": "0 if attn_metadata is None or attn_metadata.max_query_len > 1 else attn_metadata.seq_lens.numel() * ((attn_metadata.max_seq_len - 1) // 32)",
      "rationale": "Counts additional context blocks traversed during decode."
    }
  ],
  "hypothesis": "Previous block products overcounted causal prefill work: only query rows beyond position 32 visit a second KV block. Counting those rows directly may explain the missing native kernel work."
}
